def geodesic_predict(grid,target,seed_colors):
 from collections import deque
 n,m=grid.shape; res=grid.copy(); Ds=[]
 for col in seed_colors:
  dd=np.full((n,m),999); q=deque()
  for r,c in np.argwhere(grid==target):
   if any(0<=r+dr<n and 0<=c+dc<m and grid[r+dr,c+dc]==col for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
    dd[r,c]=1; q.append((r,c))
  while q:
   r,c=q.popleft()
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    rr,cc=r+dr,c+dc
    if 0<=rr<n and 0<=cc<m and grid[rr,cc]==target and dd[rr,cc]>dd[r,c]+1:
     dd[rr,cc]=dd[r,c]+1; q.append((rr,cc))
  Ds.append(dd)
 for r,c in np.argwhere(grid==target):
  ds=[d[r,c] for d in Ds]; ix=np.argmin(ds)
  if ds.count(min(ds))==1 and ds[ix]<999: res[r,c]=seed_colors[ix]
 return res,Ds
